import json,glob,csv,os,datetime
meth={r['session_id']:r['method'] for r in csv.DictReader(open('exports/sessions.csv'))}
rows=[]
for f in glob.glob('logs/sessions/practice/*.json'):
  d=json.load(open(f)); r=d.get('result') or {}
  if not r.get('deal') or r.get('score') is None: continue
  sid=d['session_id']; c=d['case_id'][5:]
  run=glob.glob(f'logs/runs/{c}_{sid}.json')
  rows.append((c,r['score'],sid,bool(run),meth.get(sid,'-'),datetime.datetime.fromtimestamp(os.path.getmtime(f)).strftime('%a %H:%M'),r['c_open']-r['c_deal']))
import collections
by=collections.defaultdict(list)
for x in rows: by[x[0]].append(x)
for c in sorted(by):
  top=sorted(by[c],key=lambda x:-x[1])[:3]
  for t in top: print(c, round(t[1],3), t[2], 'run' if t[3] else 'norun', t[4][:30], t[5])
